;---------------------------------------------------------------------------------------------------
; Trap_SCI_SPI_RTI  ($8D7F)  -- interrupt vector: SCI, SPI, RTI
;
; Unexpected-interrupt trap for the SCI, SPI and real-time interrupt vectors (cause code $01).
; [reviewed]
;
; None of these interrupts is enabled in normal operation. Like all Trap_* stubs it loads its
; cause bit into B and joins Trap_IRQ, which records the cause and restarts the controller.
;---------------------------------------------------------------------------------------------------
Trap_SCI_SPI_RTI:
        ldab    #$01
        bra     L8D9D


