;---------------------------------------------------------------------------------------------------
; Trap_IRQ  ($8D9B)  -- interrupt vector: IRQ
;
; Common trap handler; the IRQ pin itself enters here with cause code $80. [reviewed]
;
; ORs the cause bit into BYTE00 and copies a word from the interrupt stack frame (intended as the
; interrupted program counter) to BYTE01/BYTE02, so the fault can be read out later. It then
; resets the stack and repeats the hardware initialisation of ResetInterrupt; because RAM is not
; cleared on this path, the warm-start check keeps adaptive memory and fault codes. (The original
; disassembly called this routine "Interrupt_CrankSensor_Signal"; the crank sensor actually uses
; the pulse accumulator input, see Isr_PAI_CrankSensor.)
;---------------------------------------------------------------------------------------------------
Trap_IRQ:
        ldab    #$80
L8D9D:
        sei
        stab    <Temp0
        orab    <BYTE00
        stab    <BYTE00
        tsx
        ldd     $08,x
        std     <Temp1
        std     <BYTE01
        lds     #$04FF
        ldx     #REGS
        ldd     #$B911
        staa    $39,x                                ; OPTION: System configuration options
        stab    $24,x                                ; TMSK2: Timer interrupt mask 2 (TOI, RTII, PAOVI, PAII, prescaler)
        ldaa    #$00
        staa    $35,x                                ; BPROT: EEPROM block protect
        ldd     #$4022
        brset   $00,x,#$80,L8DC5                     ; PORTA: Port A data (timer pins: IC1-IC3, OC2-OC5, PAI)
        oraa    #$10
L8DC5:
        staa    $26,x
        stab    $3C,x
        clr     $0C,x
        ldd     #$2A1A
        staa    $20,x
        stab    $21,x
        ldaa    #$38
        staa    $0B,x
        ldab    #$02
        stab    <BitFlags_AIS
        ldd     <BYTE03
        std     <Temp3
        ldd     #$AAA5
        cpd     <BYTE03
        beq     L8E47
        decb
        stab    <Temp4
        bra     L8E47
